1	package com.cc91.service;
2	
3	import com.cc91.dto.CommentResponse;
4	import com.cc91.dto.CreateCommentRequest;
5	import com.cc91.entity.Comment;
6	import com.cc91.entity.Post;
7	import com.cc91.entity.User;
8	import com.cc91.exception.ResourceNotFoundException;
9	import com.cc91.exception.UnauthorizedException;
10	import com.cc91.repository.CommentRepository;
11	import com.cc91.repository.PostRepository;
12	import com.cc91.repository.UserRepository;
13	import org.slf4j.Logger;
14	import org.slf4j.LoggerFactory;
15	import org.springframework.stereotype.Service;
16	import org.springframework.transaction.annotation.Transactional;
17	
18	import java.util.ArrayList;
19	import java.util.HashMap;
20	import java.util.List;
21	import java.util.Map;
22	import java.util.stream.Collectors;
23	
24	/**
25	 * 评论服务
26	 */
27	@Service
28	public class CommentService {
29	
30	    private static final Logger logger = LoggerFactory.getLogger(CommentService.class);
31	
32	    private final CommentRepository commentRepository;
33	    private final PostRepository postRepository;
34	    private final UserRepository userRepository;
35	
36	    public CommentService(CommentRepository commentRepository,
37	                         PostRepository postRepository,
38	                         UserRepository userRepository) {
39	        this.commentRepository = commentRepository;
40	        this.postRepository = postRepository;
41	        this.userRepository = userRepository;
42	    }
43	
44	    /**
45	     * 创建评论
46	     */
47	    @Transactional
48	    public CommentResponse createComment(String username, Long postId, CreateCommentRequest request) {
49	        User user = userRepository.findByUsername(username)
50	                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));
51	
52	        Post post = postRepository.findById(postId)
53	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
54	
55	        Comment comment = new Comment(postId, user.getId(), request.getContent(), null);
56	        comment = commentRepository.save(comment);
57	
58	        logger.info("评论创建成功: id={}, postId={}, author={}", comment.getId(), postId, username);
59	
60	        return toCommentResponse(comment, user.getUsername());
61	    }
62	
63	    /**
64	     * 回复评论
65	     */
66	    @Transactional
67	    public CommentResponse replyToComment(String username, Long commentId, CreateCommentRequest request) {
68	        User user = userRepository.findByUsername(username)
69	                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));
70	
71	        Comment parentComment = commentRepository.findById(commentId)
72	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
73	
74	        Comment reply = new Comment(parentComment.getPostId(), user.getId(),
75	                                    request.getContent(), commentId);
76	        reply = commentRepository.save(reply);
77	
78	        logger.info("回复评论成功: id={}, parentId={}, author={}", reply.getId(), commentId, username);
79	
80	        return toCommentResponse(reply, user.getUsername());
81	    }
82	
83	    /**
84	     * 删除评论（软删除）
85	     */
86	    @Transactional
87	    public void deleteComment(String username, Long commentId) {
88	        User user = userRepository.findByUsername(username)
89	                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));
90	
91	        Comment comment = commentRepository.findById(commentId)
92	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
93	
94	        // 验证作者权限
95	        if (!comment.getAuthorId().equals(user.getId())) {
96	            throw new UnauthorizedException("无权限删除此评论");
97	        }
98	
99	        // 软删除
100	        comment.setStatus("DELETED");
101	        commentRepository.save(comment);
102	
103	        logger.info("评论删除成功: id={}, author={}", commentId, username);
104	    }
105	
106	    /**
107	     * 获取帖子的所有评论（树形结构）
108	     */
109	    @Transactional(readOnly = true)
110	    public List<CommentResponse> getCommentsByPostId(Long postId) {
111	        Post post = postRepository.findById(postId)
112	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
113	
114	        // 查询所有已发布的评论
115	        List<Comment> comments = commentRepository.findByPostIdAndStatusOrderByCreatedAtAsc(postId, "PUBLISHED");
116	
117	        // 构建用户名映射
118	        Map<Long, String> userMap = new HashMap<>();
119	        for (Comment comment : comments) {
120	            if (!userMap.containsKey(comment.getAuthorId())) {
121	                User author = userRepository.findById(comment.getAuthorId()).orElse(null);
122	                userMap.put(comment.getAuthorId(), author != null ? author.getUsername() : "未知用户");
123	            }
124	        }
125	
126	        // 构建树形结构
127	        return buildCommentTree(comments, userMap);
128	    }
129	
130	    /**
131	     * 构建评论树形结构
132	     */
133	    private List<CommentResponse> buildCommentTree(List<Comment> comments, Map<Long, String> userMap) {
134	        // 转换为 CommentResponse
135	        List<CommentResponse> responses = comments.stream()
136	                .map(comment -> toCommentResponse(comment, userMap.get(comment.getAuthorId())))
137	                .collect(Collectors.toList());
138	
139	        // 构建 ID 到 Response 的映射
140	        Map<Long, CommentResponse> responseMap = new HashMap<>();
141	        for (CommentResponse response : responses) {
142	            responseMap.put(response.getId(), response);
143	        }
144	
145	        // 构建树形结构
146	        List<CommentResponse> rootComments = new ArrayList<>();
147	        for (CommentResponse response : responses) {
148	            if (response.getParentId() == null) {
149	                // 顶级评论
150	                rootComments.add(response);
151	            } else {
152	                // 子评论，添加到父评论的 replies 中
153	                CommentResponse parent = responseMap.get(response.getParentId());
154	                if (parent != null) {
155	                    parent.getReplies().add(response);
156	                }
157	            }
158	        }
159	
160	        return rootComments;
161	    }
162	
163	    /**
164	     * 转换为 CommentResponse
165	     */
166	    private CommentResponse toCommentResponse(Comment comment, String authorUsername) {
167	        return new CommentResponse(
168	                comment.getId(),
169	                comment.getPostId(),
170	                comment.getAuthorId(),
171	                authorUsername,
172	                comment.getContent(),
173	                comment.getParentId(),
174	                comment.getCreatedAt(),
175	                comment.getStatus()
176	        );
177	    }
178	}
